        }

        canvasResizetoDataURL (canvas, quality) {
          return canvas.toDataURL(this.type, quality)
        }

        filetoDataURL (file, fn) {
          var reader = new FileReader()
          reader.readAsDataURL(file)
          reader.onloadend = (e) => {
            fn(e.target.result)
          }
        }

        dataURLtoImage (dataurl, fn) {
          var img = new Image()
          img.src = dataurl
          img.onload = () => {
            fn(img)
          }
        }

        dataURLtoFile (dataurl) {
